cd $TMPDIR/p && ls -la props.json && jq 'length' props.json && jq -c '.[0]' props.json && python3 -I - props.json <<'EOF'
import json,sys
a=json.load(open(sys.argv[1])); tot=len(json.dumps(a,separators=(',',':')))
from collections import Counter
c=Counter()
for s in a:
    for k,v in s.items():
        if k=='reference':
            for kk,vv in v.items():
                if kk=='file':
                    for k3,v3 in vv.items(): c['reference.file.'+k3]+=len(json.dumps(v3))+len(k3)+3
                else: c['reference.'+kk]+=len(json.dumps(vv))+len(kk)+3
        else: c[k]+=len(json.dumps(v,separators=(',',':')))+len(k)+3
print('symbols',len(a),'bytes',tot,'per',tot//len(a))
for k,v in c.most_common(): print(f'{k:28} {v:8} {100*v/tot:5.1f}%')
EOF

