python3 - <<'EOF'
p='crates/semantic/src/rpc.rs'
s=open(p).read()
old='''        let params = serde_json::to_vec(params)
            .map_err(|error| CallError::Fatal(format!("failed to serialize a request: {error}")))?;
        let Some(log) = &self.recording else {
            return self.client.request_raw(method, params, self.deadline).await.map_err(classify);
        };'''
new='''        let params = serde_json::to_vec(params)
            .map_err(|error| CallError::Fatal(format!("failed to serialize a request: {error}")))?;
        let memoize = self.recording.is_none()
            && std::env::var_os("CALIPER_MEMO").is_some()
            && !matches!(method, "updateSnapshot" | "createSnapshot" | "release" | "parseConfigFile");
        if memoize {
            let mut key = method.as_bytes().to_vec();
            key.extend_from_slice(&params);
            let hit = EXPERIMENT_MEMO.lock().unwrap().get(&key).cloned();
            if let Some(hit) = hit {
                *EXPERIMENT_HITS.lock().unwrap().entry(method).or_default() += (1, hit.get().len() as u64);
                return Ok(hit);
            }
            let answer = self.client.request_raw(method, params, self.deadline).await.map_err(classify)?;
            EXPERIMENT_MEMO.lock().unwrap().insert(key, answer.clone());
            return Ok(answer);
        }
        let Some(log) = &self.recording else {
            return self.client.request_raw(method, params, self.deadline).await.map_err(classify);
        };'''
assert old in s
s=s.replace(old,new)
s=s.replace('''fn classify(error: RequestError) -> CallError {''','''type HitTable = std::collections::BTreeMap<&'static str, (u64, u64)>;
static EXPERIMENT_MEMO: std::sync::LazyLock<Mutex<rustc_hash::FxHashMap<Vec<u8>, Box<RawValue>>>> =
    std::sync::LazyLock::new(Mutex::default);
static EXPERIMENT_HITS: std::sync::LazyLock<Mutex<HitTable>> = std::sync::LazyLock::new(Mutex::default);

/// Experiment only: prints the memo's hits by method.
pub(crate) fn print_memo_hits() {
    if std::env::var_os("CALIPER_MEMO").is_none() {
        return;
    }
    for (method, (hits, bytes)) in EXPERIMENT_HITS.lock().unwrap().iter() {
        eprintln!("MEMO {method} hits={hits} bytes={bytes}");
    }
}

fn classify(error: RequestError) -> CallError {''',1)
open(p,'w').write(s)
p='crates/semantic/src/lib.rs'
s=open(p).read()
old='''    outcome.diagnostics.extend(watch.diagnostic(left));
'''
assert s.count(old)==1
s=s.replace(old, old+'''    crate::rpc::print_memo_hits();
''')
open(p,'w').write(s)
EOF
