    /// Chakra's run read 17,592,186,044,414 MiB and left all 620 components structural: the counter at -2 MiB.
    #[test]
    fn a_commit_counter_below_zero_reads_as_nothing() {
        let minus_two_mib = (-(2_isize << 20)).cast_unsigned();

        assert_eq!(from_signed(minus_two_mib), 0);
        assert!(!Watch::new(Some(HeapBudget::new(MAX_HEAP_BUDGET))).past_at(from_signed(minus_two_mib)));
    }

